<?php
require_once __DIR__.'/../includes/bootstrap.php';
require_once __DIR__.'/../includes/Exporter.php';
$workspace=require_permission('view');$user=require_login();if(!plan_limits($workspace)['exports']){http_response_code(403);exit('Ekspor report tersedia pada Pro atau Business.');}$id=filter_var($_GET['id']??null,FILTER_VALIDATE_INT);$format=(string)($_GET['format']??'csv');if(!in_array($format,['csv','xlsx'],true)){http_response_code(400);exit('Format tidak didukung.');}$st=$GLOBALS['pdo']->prepare('SELECT r.*,d.name dataset_name FROM reports r LEFT JOIN datasets d ON d.id=r.dataset_id WHERE r.id=? AND r.workspace_id=? LIMIT 1');$st->execute([$id,$workspace['id']]);$report=$st->fetch();if(!$report){http_response_code(404);exit('Report tidak ditemukan.');}$result=json_decode((string)$report['result_json'],true)?:[];$headers=['Jenis','Nama metrik','Nilai','Jumlah baris'];$rows=[];foreach(($result['metrics']??[]) as $metric)$rows[]=['Indikator',(string)($metric['label']??''),(string)($metric['value']??''),''];foreach(($result['table']??[]) as $row)$rows[]=['Perincian',(string)($row['label']??''),(string)($row['value']??''),(string)($row['rows']??'')];if(!$rows)$rows[]=['Report',(string)$report['title'],(string)($report['summary']??''),''];$GLOBALS['pdo']->prepare('INSERT INTO usage_logs(workspace_id,user_id,usage_type,units,month_key,metadata_json) VALUES(?,? ,"export",1,?,?)')->execute([$workspace['id'],$user['id'],date('Y-m'),json_encode(['report_id'=>(int)$report['id'],'format'=>$format])]);audit_log('report.exported','report',(int)$report['id'],['format'=>$format]);$filename='datanix-report-'.preg_replace('/[^a-z0-9-]/i','-',slugify((string)$report['title']));if($format==='xlsx')DatanixExporter::xlsx($headers,$rows,$filename.'.xlsx');DatanixExporter::csv($headers,$rows,$filename.'.csv');
